-- Migrasi + seed untuk fitur "Kelola Sebaran Bangunan" (data GIS bangunan
-- milik daerah yang tampil di peta Analisa Kerusakan & Spasial).
-- Sebelumnya data ini statis di gis-data.js; sekarang pindah ke tabel
-- supaya bisa ditambah / diubah / dihapus oleh admin (Admin::bangunan*).
--
-- Jalankan lewat phpMyAdmin -> pilih database -> tab SQL -> paste -> Go.
-- Seed hanya dimuat kalau tabel `bangunan_gis` masih kosong, jadi aman
-- dijalankan ulang (tidak menggandakan baris).

CREATE TABLE IF NOT EXISTS `bangunan_gis` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `opd` VARCHAR(200) DEFAULT NULL,
  `unit` VARCHAR(200) DEFAULT NULL,
  `institusi` VARCHAR(200) DEFAULT NULL,
  `nama_bangunan` VARCHAR(255) NOT NULL,
  `fungsi` VARCHAR(100) DEFAULT NULL,
  `jumlah_lantai` INT UNSIGNED DEFAULT NULL,
  `kecamatan` VARCHAR(100) DEFAULT NULL,
  `kelurahan` VARCHAR(100) DEFAULT NULL,
  `alamat` TEXT,
  `kondisi` ENUM('1','2','3','4') NOT NULL DEFAULT '1' COMMENT '1=Baik 2=Rusak Ringan 3=Rusak Sedang 4=Rusak Berat',
  `latitude` DECIMAL(11,8) NOT NULL,
  `longitude` DECIMAL(11,8) NOT NULL,
  `foto` VARCHAR(255) DEFAULT NULL COMMENT 'URL foto bangunan (opsional)',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_bangunan_kecamatan` (`kecamatan`),
  KEY `idx_bangunan_kondisi` (`kondisi`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

